#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_FIELDS 64
#define MAX_KEY_LEN 128
#define MAX_VAL_LEN 512
#define PROTO_MAGIC 0xDE4D
#define ENCRYPT_KEY 0xA7

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
    uint8_t flags;
} Field;

typedef struct {
    Field fields[MAX_FIELDS];
    int count;
    uint8_t frozen;
    uint8_t proto_inherit;
} Object;

typedef struct {
    Object* prototype;
    Object* instance;
} ObjectChain;

static void xor_encrypt(char* buf, size_t len) {
    for (size_t i = 0; i < len; i++)
        buf[i] ^= ENCRYPT_KEY;
}

static void xor_decrypt(char* buf, size_t len) {
    xor_encrypt(buf, len); // XOR is symmetric
}

int object_init(Object* obj) {
    memset(obj, 0, sizeof(Object));
    obj->count = 0;
    obj->frozen = 0;
    obj->proto_inherit = 1;
    return 0;
}

int object_set(Object* obj, const char* key, const char* value, uint8_t flags) {
    if (obj->frozen) return -1;
    if (!key || !value) return -1;
    if (strlen(key) >= MAX_KEY_LEN || strlen(value) >= MAX_VAL_LEN) return -1;

    // Update existing field
    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->fields[i].key, key) == 0) {
            strncpy(obj->fields[i].value, value, MAX_VAL_LEN - 1);
            obj->fields[i].flags = flags;
            return 0;
        }
    }

    if (obj->count >= MAX_FIELDS) return -1;
    strncpy(obj->fields[obj->count].key, key, MAX_KEY_LEN - 1);
    strncpy(obj->fields[obj->count].value, value, MAX_VAL_LEN - 1);
    obj->fields[obj->count].flags = flags;
    obj->count++;
    return 0;
}

const char* object_get(ObjectChain* chain, const char* key) {
    // Search instance first
    for (int i = 0; i < chain->instance->count; i++) {
        if (strcmp(chain->instance->fields[i].key, key) == 0)
            return chain->instance->fields[i].value;
    }
    // Fall through to prototype if inheritance enabled
    if (chain->instance->proto_inherit && chain->prototype) {
        for (int i = 0; i < chain->prototype->count; i++) {
            if (strcmp(chain->prototype->fields[i].key, key) == 0)
                return chain->prototype->fields[i].value;
        }
    }
    return NULL;
}

int serialize_to_encrypted(Object* obj, const char* filepath) {
    FILE* f = fopen(filepath, "wb");
    if (!f) return -1;

    uint16_t magic = PROTO_MAGIC;
    fwrite(&magic, sizeof(magic), 1, f);
    fwrite(&obj->count, sizeof(obj->count), 1, f);
    fwrite(&obj->frozen, sizeof(obj->frozen), 1, f);
    fwrite(&obj->proto_inherit, sizeof(obj->proto_inherit), 1, f);

    for (int i = 0; i < obj->count; i++) {
        char enc_key[MAX_KEY_LEN];
        char enc_val[MAX_VAL_LEN];
        memcpy(enc_key, obj->fields[i].key, MAX_KEY_LEN);
        memcpy(enc_val, obj->fields[i].value, MAX_VAL_LEN);
        xor_encrypt(enc_key, MAX_KEY_LEN);
        xor_encrypt(enc_val, MAX_VAL_LEN);
        fwrite(enc_key, MAX_KEY_LEN, 1, f);
        fwrite(enc_val, MAX_VAL_LEN, 1, f);
        fwrite(&obj->fields[i].flags, sizeof(uint8_t), 1, f);
    }
    fclose(f);
    return 0;
}

int deserialize_from_encrypted(Object* obj, const char* filepath) {
    FILE* f = fopen(filepath, "rb");
    if (!f) return -1;

    uint16_t magic;
    if (fread(&magic, sizeof(magic), 1, f) != 1) { fclose(f); return -1; }
    if (magic != PROTO_MAGIC) { fclose(f); return -1; }

    int file_count;
    if (fread(&file_count, sizeof(file_count), 1, f) != 1) { fclose(f); return -1; }
    if (fread(&obj->frozen, sizeof(obj->frozen), 1, f) != 1) { fclose(f); return -1; }
    if (fread(&obj->proto_inherit, sizeof(obj->proto_inherit), 1, f) != 1) { fclose(f); return -1; }

    // Bounds check: clamp count to valid range
    if (file_count < 0 || file_count > MAX_FIELDS) {
        fclose(f);
        return -1;
    }
    obj->count = file_count;

    for (int i = 0; i < obj->count; i++) {
        char enc_key[MAX_KEY_LEN];
        char enc_val[MAX_VAL_LEN];
        if (fread(enc_key, MAX_KEY_LEN, 1, f) != 1) { obj->count = i; fclose(f); return -1; }
        if (fread(enc_val, MAX_VAL_LEN, 1, f) != 1) { obj->count = i; fclose(f); return -1; }
        xor_decrypt(enc_key, MAX_KEY_LEN);
        xor_decrypt(enc_val, MAX_VAL_LEN);
        memcpy(obj->fields[i].key, enc_key, MAX_KEY_LEN);
        memcpy(obj->fields[i].value, enc_val, MAX_VAL_LEN);
        if (fread(&obj->fields[i].flags, sizeof(uint8_t), 1, f) != 1) { obj->count = i + 1; fclose(f); return -1; }
    }
    fclose(f);
    return 0;
}

// Merge deserialized data into instance only - no prototype access
int merge_into_chain(ObjectChain* chain, Object* source) {
    for (int i = 0; i < source->count; i++) {
        const char* key = source->fields[i].key;
        // Reject keys attempting prototype pollution
        if (key[0] == '_' && key[1] == '_') {
            continue; // Skip dangerous keys
        }
        object_set(chain->instance, key, 
                  source->fields[i].value, source->fields[i].flags);
    }
    return 0;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s <datafile>\n", argv[0]);
        return 1;
    }

    Object proto, instance, loaded;
    ObjectChain chain = { .prototype = &proto, .instance = &instance };

    object_init(&proto);
    object_init(&instance);
    object_init(&loaded);

    // Set default prototype values
    object_set(&proto, "role", "user", 0);
    object_set(&proto, "admin", "false", 0);
    proto.frozen = 1; // Freeze prototype

    // Load untrusted data
    if (deserialize_from_encrypted(&loaded, argv[1]) == 0) {
        merge_into_chain(&chain, &loaded);
    }

    const char* role = object_get(&chain, "role");
    const char* admin = object_get(&chain, "admin");
    printf("Role: %s, Admin: %s\n", role ? role : "none", admin ? admin : "none");

    return 0;
}
